import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        while (scanner.hasNext()) {
            String line = scanner.next();
            int lengthLine = line.length();
            StringBuilder output = new StringBuilder();
            int mark = 0;
            for (int index = 0; index < lengthLine; index++) {
                if (line.charAt(index) == 'd' && index != 0 && index <= lengthLine - 4
                        && line.charAt(index + 1) == 'o' && line.charAt(index + 2) == 't') {
                    output.append('.');
                    index += 2;
                } else if (line.charAt(index) == 'a' && index != 0 && index <= lengthLine - 2
                        && line.charAt(index + 1) == 't' && mark == 0) {
                    output.append('@');
                    mark = 1;
                    index++;
                } else {
                    output.append(line.charAt(index));
                }
            }
            System.out.println(output.toString());
        }
        scanner.close();
    }
}
